function slotcarResearchTools(c){return panel('Research this slotcar',`<p>Identify the miniature by its manufacturer and exact product reference. Give the template to your own AI, then choose which suggestions to import.</p><p><strong>${esc(c.maker||'Manufacturer not set')}</strong> · ${esc(c.reference||'Product reference not set')} · ${esc(c.scale||'Scale not set')}</p><div class="actions">${btn('Download slotcar template','slotcar-kit','',c.id)}${btn('Import slotcar research…','slotcar-pick','',c.id)}</div><p class="tiny muted mt">English instructions ask for five independent sources, with three agreeing per verified specification. Source URLs are optional. Factory specifications stay separate from your modifications. No built-in AI or automatic website lookup.</p>`);}
function slotcarResearchContext(id){const c=db.cars.find(c=>c.id===id);if(!c)throw Error('Car not found.');return {databaseId:db.id,carId:id,revision:c.revision,path:dataPath,car:{hasInstalledParts:db.installations.some(i=>i.carId===id&&!i.removed),maker:c.maker,reference:c.reference,scale:c.scale,factory:structuredClone(c.factory||{}),technical:structuredClone(c.technical||{}),...Object.fromEntries(Object.keys(SlotcarResearch.identity).map(k=>[k,c[k]||'']))}};}
function checkSlotcarResearch(ctx){if(!local()||db.id!==ctx.databaseId||dataPath!==ctx.path||db.cars.find(c=>c.id===ctx.carId)?.revision!==ctx.revision)throw Error('The car or collection changed. Reopen slotcar research.');}
function reviewSlotcarResearch(ctx,result){
 checkSlotcarResearch(ctx);ctx.car.hasInstalledParts=result.hasInstalledParts===true;const m=result.identification;
 modal('Review slotcar product research',`<p><strong>${esc(m.maker)} · ${esc(m.reference)}</strong>${m.scale?' · '+esc(m.scale):''}</p><p class="note info">The file claims an exact product match. Verification statements are reported by your AI, not independently checked by Paddock; check the product variant. Choose each field to import. Selected identity and factory values replace those fields. Unknown and unchecked fields stay unchanged.</p>${m.uncertainty?'<p class="note">'+esc(m.uncertainty)+'</p>':''}<div class="actions">${m.sourceUrls.map(url=>historySourceButton(url,result.sources.find(s=>s.url===url)?.title||url)).join('')}</div><div data-review-selection>${ReviewSelection.toolbar()}<div class="research-proposals">${result.proposals.map((p,i)=>{const factory=p.field.startsWith('factory.'),old=factory?ctx.car.factory[p.field.slice(8)]:ctx.car[p.field];return `<article class="research-proposal"><label class="check"><input type="checkbox" data-review-choice name="slotcar-field-${i}"> <strong>${esc(SlotcarResearch.labels[p.field])}</strong> ${badge(factory?'Factory reference':'Car identity')}</label><div class="research-values"><div><span class="tiny muted">Saved value</span><p class="prewrap">${esc(old||'—')}</p></div><div><span class="tiny muted">Proposed value</span><p class="prewrap">${esc(p.value)}</p></div></div><p class="tiny muted prewrap">${esc(p.uncertainty||'No verification details supplied. Check this specification before accepting.')}</p>${p.sourceUrls.map(url=>historySourceButton(url,result.sources.find(s=>s.url===url)?.title||url)).join('')}</article>`;}).join('')}</div></div><label class="check-row mt"><input type="checkbox" name="fillEmpty" ${SlotcarResearch.canInitialize(ctx.car)?'':'disabled'}>Also initialise the empty current configuration from selected factory values</label><p class="tiny muted">Only available when there are no current specifications or installed parts, so factory ratings cannot be mixed with an upgraded motor or changed gearing. This does not install inventory or alter historical setups and race results. Sources and uncertainty are appended to Factory reference → Technical notes.</p><label class="check-row mt"><input type="checkbox" name="confirmed" required>I checked that the manufacturer, full product reference and variant match my slotcar.</label>`,async values=>{
  checkSlotcarResearch(ctx);if(!values.confirmed)throw Error('Confirm the product match.');const indices=Object.keys(values).filter(k=>k.startsWith('slotcar-field-')).map(k=>Number(k.slice(14)));
  const data=SlotcarResearch.patch(ctx.car,result,indices,!!values.fillEmpty);await change('car.save',{id:ctx.carId,revision:ctx.revision,data});
 },'Import selected fields');
}
async function slotcarResearchAction(action,id){
 if(!['slotcar-research','slotcar-kit','slotcar-pick'].includes(action))return false;if(!local())throw Error('Switch to your own collection to research a slotcar.');
 const ctx=slotcarResearchContext(id);if(action==='slotcar-research'){modal('Slotcar product research',slotcarResearchTools(db.cars.find(c=>c.id===id)),null);return true;}
 const request={databaseId:ctx.databaseId,carId:id,revision:ctx.revision};
 if(action==='slotcar-kit'){if(await api('file','slotcar.kit',request))toast('Slotcar template saved. Give it to your own AI, then import its completed JSON.');return true;}
 const result=await api('file','slotcar.pick',request);if(result)reviewSlotcarResearch(ctx,result);return true;
}
